<?php
require 'config.php';require 'includes/functions.php';verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'){$action=$_POST['action']??'';$id=(int)($_POST['product_id']??0);if($action==='add'){$s=$pdo->prepare("SELECT id,stock FROM products WHERE id=? AND active=1");$s->execute([$id]);$p=$s->fetch();if($p&&$p['stock']>0){$_SESSION['cart'][$id]=min((int)$p['stock'],($_SESSION['cart'][$id]??0)+max(1,(int)($_POST['quantity']??1)));flash('Added to your bag.');}else flash('This item is unavailable.','error');}elseif($action==='update'){foreach($_POST['qty']??[] as $pid=>$qty){$pid=(int)$pid;$qty=(int)$qty;if($qty<=0)unset($_SESSION['cart'][$pid]);else{$s=$pdo->prepare("SELECT stock FROM products WHERE id=? AND active=1");$s->execute([$pid]);$stock=$s->fetchColumn();if($stock)$_SESSION['cart'][$pid]=min($qty,(int)$stock);}}flash('Bag updated.');}elseif($action==='remove'){unset($_SESSION['cart'][$id]);flash('Item removed.');}go('cart.php');}
$items=[];$total=0;if(!empty($_SESSION['cart'])){$ids=array_map('intval',array_keys($_SESSION['cart']));$in=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT * FROM products WHERE active=1 AND id IN ($in)");$s->execute($ids);$items=$s->fetchAll();foreach($items as $p)$total+=$p['price']*$_SESSION['cart'][$p['id']];}$title='Shopping bag';require 'includes/header.php';?><div class="page-head"><span class="eyebrow">YOUR SELECTION</span><h1>Shopping bag</h1></div><?php if(!$items):?><div class="empty"><h2>Your bag is waiting for a good outfit.</h2><a class="button dark" href="index.php">Continue shopping</a></div><?php else:?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="update"><div class="cart-layout"><div><?php foreach($items as $p):?><div class="cart-row"><img src="<?=e($p['image_url'])?>" alt=""><div class="cart-desc"><b><?=e($p['name'])?></b><small><?=e($p['subcategory'])?></small><b><?=money($p['price'])?></b><label>Qty<input type="number" name="qty[<?=$p['id']?>]" value="<?=$_SESSION['cart'][$p['id']]?>" min="0" max="<?=$p['stock']?>"></label><button class="link" type="submit" form="remove<?=$p['id']?>">Remove</button></div></div><?php endforeach;?><button class="button outline">Update bag</button></div><aside class="summary"><h2>Order summary</h2><p>Subtotal <b><?=money($total)?></b></p><p>Shipping <b><?=$total>=1999?'FREE':'Calculated at checkout'?></b></p><hr><h2><?=money($total)?></h2><a class="button dark full" href="checkout.php">Proceed to checkout</a></aside></div></form><?php foreach($items as $p):?><form id="remove<?=$p['id']?>" method="post"><?=csrf_field()?><input type="hidden" name="action" value="remove"><input type="hidden" name="product_id" value="<?=$p['id']?>"></form><?php endforeach;?><?php endif;?><?php require 'includes/footer.php';?>